import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        String bestKanal = "";
        long bestFoyda = Long.MIN_VALUE;
        while (in.hasNext()) {
            String kanal = in.next();
            long tashrif = in.nextLong(), buyurtma = in.nextLong(), tushum = in.nextLong(), reklama = in.nextLong();
            double konversiya = 100.0 * buyurtma / tashrif;
            long chek = tushum / buyurtma;
            long cac = reklama / buyurtma;
            double roas = (double) tushum / reklama;
            long foyda = tushum * 30 / 100 - reklama;
            if (foyda > bestFoyda) {
                bestFoyda = foyda;
                bestKanal = kanal;
            }
            System.out.println(String.format("%s: conversion %.2f%%, average order %d, CAC %d, ROAS %.2f", kanal, konversiya, chek, cac, roas));
        }
        System.out.println("best: " + bestKanal);
    }
}

